CREATE TABLE IF NOT EXISTS ha_project (id BIGINT AUTO_INCREMENT PRIMARY KEY, enterprise_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, entitlement_mode VARCHAR(32) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) COMMENT='项目';
CREATE TABLE IF NOT EXISTS ha_api_key (id BIGINT AUTO_INCREMENT PRIMARY KEY, enterprise_id BIGINT NOT NULL, project_id BIGINT NOT NULL, key_name VARCHAR(128) NOT NULL, key_prefix VARCHAR(32) NOT NULL, key_hash VARBINARY(64) NOT NULL, status VARCHAR(16) NOT NULL, expires_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_api_key_scope(enterprise_id,project_id)) COMMENT='API密钥';
CREATE TABLE IF NOT EXISTS ha_ai_request (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(64) NOT NULL, enterprise_id BIGINT NULL, project_id BIGINT NULL, model VARCHAR(128) NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) COMMENT='AI请求';
CREATE TABLE IF NOT EXISTS ha_ai_routing_attempt (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_id BIGINT NOT NULL, provider VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) COMMENT='路由尝试';
CREATE TABLE IF NOT EXISTS ha_project_model_policy (id BIGINT AUTO_INCREMENT PRIMARY KEY, project_id BIGINT NOT NULL, model VARCHAR(128) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uk_project_model(project_id,model)) COMMENT='项目模型策略';
